/**
 * Current Material Symbols are drawn on a 960 unit grid whose origin is the bottom-left corner
 * (`viewBox="0 -960 960 960"`), so the path is shifted down by one grid height. A few older
 * symbols are still on the plain 24 unit grid and are used as they are.
 */
private fun symbol(name: String, pathData: String, autoMirror: Boolean = false, grid: Float = 960f): ImageVector {
    val builder = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = grid,
        viewportHeight = grid,
        autoMirror = autoMirror,
    )
    val fill = SolidColor(Color.Black)
    return if (grid == 960f) {
        builder.addGroup(translationY = grid)
            .addPath(pathData = addPathNodes(pathData), fill = fill)
            .clearGroup()
            .build()
    } else {
        builder.addPath(pathData = addPathNodes(pathData), fill = fill).build()
    }
}
